def f(inp):
    H=len(inp); W=len(inp[0])
    fours=[(i,j) for i in range(H) for j in range(W) if inp[i][j]==4]
    obj=[(i,j) for i in range(H) for j in range(W) if inp[i][j]==8]
    rows=[i for i,_ in obj]; cols=[j for _,j in obj]
    r0,r1,c0,c1=min(rows),max(rows),min(cols),max(cols)
    A=[[1 if (i,j) in obj else 0 for j in range(c0,c1+1)] for i in range(r0,r1+1)]
    h=len(A)
    out=[[0]* (3*len(fours)) for _ in range(3)]
    for k,(i,j) in enumerate(fours):
        src_row = 2 - (h-1)  # bottom-align: object last row -> output row 2
        for a in range(h):
            for b in range(3):
                out[src_row+a][3*k+b] = A[a][b]
    return out

